/** Which sockets receive an emit to `room` from processes[fromIndex]? */
function deliveredTo(processes, fromIndex, room, withAdapter) {
  // Write your solution here
  const out = [];
  for (const p of processes) for (const [id, rooms] of Object.entries(p.sockets)) if (rooms.includes(room)) out.push(id);
  return out;
}

/** Does Socket.IO keep working with this deployment? */
function transportWorks({ transports, sticky, processes }) {
  return true;
}

solutionCodeJson.code:
// Reference solution
function deliveredTo(processes, fromIndex, room, withAdapter) {
  // Without an adapter, a process can only see ITS OWN sockets; the adapter makes the room cluster-wide.
  const scope = withAdapter ? processes : [processes[fromIndex]];
  const out = [];
  for (const p of scope) for (const [id, rooms] of Object.entries(p.sockets)) if (rooms.includes(room)) out.push(id);
  return out.sort();
}

function transportWorks({ transports, sticky, processes }) {
  if (processes <= 1) return true;                 // one process: every request lands where its session lives
  if (sticky) return true;                         // the balancer keeps a session on one process
  // No affinity: long-polling sends request 2 to a process that has never seen the session id.
  return !transports.includes('polling');
}

