starterCodeJson.code:
/** Republish broadcasts so every process delivers to its own sockets. */
function attachAdapter(proc, redis) {
  // Write your solution here
  redis.subscribe('socket.io#/#', (raw) => {
    const m = JSON.parse(raw);
    for (const id of proc.local.get(m.room) || []) proc.deliver(id, m.event, m.data);
  });
  return {
    async emitToRoom(room, event, data) {
      await redis.publish('socket.io#/#', JSON.stringify({ from: proc.id, room, event, data }));
      return 0;
    },
  };
}

solutionCodeJson.code:
// Reference solution
function attachAdapter(proc, redis) {
  const CHANNEL = 'socket.io#/#';
  const pub = redis;
  const sub = redis.duplicate();          // MUST be its own connection: a subscribed client cannot PUBLISH
  const deliverLocal = (room, event, data) => {
    const ids = [...(proc.local.get(room) || [])];
    for (const id of ids) proc.deliver(id, event, data);
    return ids.length;
  };
  // Every process replays broadcasts from the OTHER processes to its own local sockets.
  sub.subscribe(CHANNEL, (raw) => {
    const m = JSON.parse(raw);
    if (m.from === proc.id) return;       // our own broadcast was already delivered locally
    deliverLocal(m.room, m.event, m.data);
  });
  return {
    async emitToRoom(room, event, data) {
      const local = deliverLocal(room, event, data);
      await pub.publish(CHANNEL, JSON.stringify({ from: proc.id, room, event, data }));
      return local;
    },
  };
}

