/** Broadcast that never lets one slow client grow the server's memory. */
function makeBroadcaster({ limit, maxDrops }) {
  return function broadcast(sockets, payload) {
    // Write your solution here
    const r = { sent: 0, dropped: 0, closed: 0 };
    for (const ws of sockets) { if (ws.readyState === 1) { ws.send(payload); r.sent++; } }
    return r;
  };
}

solutionCodeJson.code:
// Reference solution
function makeBroadcaster({ limit, maxDrops }) {
  const drops = new Map();                  // socket -> consecutive drops
  return function broadcast(sockets, payload) {
    const r = { sent: 0, dropped: 0, closed: 0 };
    for (const ws of sockets) {
      if (ws.readyState !== 1) continue;    // only OPEN sockets
      // readyState stays OPEN and send() never fails for a client that stopped reading:
      // bufferedAmount is the only signal that the bytes are piling up in OUR memory.
      if (ws.bufferedAmount > limit) {
        const n = (drops.get(ws) || 0) + 1;
        drops.set(ws, n);
        r.dropped++;
        if (n >= maxDrops) {
          ws.close(1013, 'slow consumer');  // 1013 "try again later": the client reconnects and refetches over REST
          drops.delete(ws);
          r.closed++;
        }
        continue;
      }
      drops.set(ws, 0);                     // keeping up again: reset the streak
      ws.send(payload);
      r.sent++;
    }
    return r;
  };
}

