/** Who is online — across every process. */
function createPresence(redis, { ttlMs }) {
  // Write your solution here (this is the per-process Set the lesson warns about)
  const online = new Set();
  return {
    async connect(userId, socketId) { const was = online.has(userId); online.add(userId); return !was; },
    async heartbeat(userId, socketId) {},
    async disconnect(userId, socketId) { online.delete(userId); return true; },
    async isOnline(userId) { return online.has(userId); },
