// Reference solution
function createPresence(redis, { ttlMs }) {
  const key = (userId, socketId) => 'presence:' + userId + ':' + socketId;
  const socketsOf = async (userId) => (await redis.keys('presence:' + userId + ':')).length;
  return {
    // One key PER SOCKET, with a TTL: a crashed process stops heartbeating and its keys expire on their own.
    async connect(userId, socketId) {
      const before = await socketsOf(userId);
      await redis.set(key(userId, socketId), '1', ttlMs);
      return before === 0;                         // true ⇒ the user just came online (emit presence:update)
    },
    async heartbeat(userId, socketId) {
      await redis.set(key(userId, socketId), '1', ttlMs);
    },
    async disconnect(userId, socketId) {
      await redis.del(key(userId, socketId));
      return (await socketsOf(userId)) === 0;      // offline only when the LAST socket of that person is gone
    },
    async isOnline(userId) {
      return (await socketsOf(userId)) > 0;
    },
    async onlineUsers() {
      const ids = new Set((await redis.keys('presence:')).map((k) => Number(k.split(':')[1])));
      return [...ids].sort((a, b) => a - b);
    },
  };
}

